def def_get_vrn_financial_account_alias_index():
    idx = {}
    import re
    def key(x):
        s = str(x or '').lower()
        s = re.sub(r'[()\[\]（）【】{}:：,，.。/／\\|｜\-_ ]+', '', s)
        return s
    for acc in VRN_FINANCIAL_ACCOUNT_SSOT:
        for a in list(acc.get('aliases', [])) + [acc.get('data_official_en', '')]:
            k = key(a)
            if k and k not in idx:
                idx[k] = acc
    return idx

